cd /c/Users/dasbl/AppData/Local/Temp/claude/adr-probes/review-ADR-0013/ && cat > p3.gd <<'EOF'
extends SceneTree
class OpeningRead extends RefCounted:
	var area: int = 0
	var area_max: int = 1
	var door_state: int = 0
class Port extends RefCounted:
	func opening_into(edge_id: int, out: OpeningRead) -> bool:
		out.area = (edge_id * 7) % 100
		out.area_max = 100
		return true
class IM extends RefCounted:
	static func floor_div(a: int, b: int) -> int:
		var q: int = a / b
		if (a % b != 0) and ((a < 0) != (b < 0)):
			q -= 1
		return q
func bad(d: Dictionary) -> int:
	var x: int = d["k"]
	return x + 1
func _init() -> void:
	var port := Port.new()
	var op := OpeningRead.new()
	var slots := PackedInt32Array()
	slots.resize(48)
	var last := PackedInt32Array()
	last.resize(48)
	var flagged := 0
	var t0 := Time.get_ticks_usec()
	for it in 1000:
		for i in 48:
			if not port.opening_into(i + 1, op):
				continue
			var area := op.area
			if area > op.area_max:
				area = op.area_max
			var leaf_w: int = 96 - IM.floor_div(96 * area, op.area_max)
			if leaf_w != last[i]:
				last[i] = leaf_w
				flagged += 1
	var t1 := Time.get_ticks_usec()
	print("hook-like loop 48 doors: ", float(t1 - t0) / 1000.0, " us/iter flagged=", flagged)
	var r = bad({"k": "str"})
	print("bad returned: ", r)
	var r2 = bad({})
	print("missing key returned: ", r2)
	quit()
EOF
